<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuth} from '../stores/auth'
import {service} from '../services'
import {useResource,useTask,confirmAction,formatDate} from '../composables/useData'
import type {Grant,Unit} from '../types/domain'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import PermissionSelector from '../components/PermissionSelector.vue'
import Icon from '../components/Icon.vue'
const route=useRoute(),router=useRouter(),grantOpened=ref(false)
const auth=useAuth(),units=useResource('units'),task=useTask(),query=ref(''),category=ref(''),status=ref(''),page=ref(1),selection=ref<string[]>([]),aclOpen=ref(false),aclId=ref(''),acl=ref<Grant[]>([])
const categories=computed(()=>[...new Set(units.items.value.filter(u=>!u.restricted).map(u=>u.category))]),filtered=computed(()=>units.items.value.filter(u=>(!query.value||`${u.title} ${u.code} ${u.tags.join(' ')}`.includes(query.value))&&(!category.value||u.category===category.value)&&(!status.value||u.status===status.value))),visible=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10))
watch([query,category,status],()=>{page.value=1;selection.value=[]})
watch(filtered,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/10)))})
const grantLabel=(u:Unit)=>!u.acl.length?'尚未配置':u.acl.some(g=>g.type==='global')?'全局可访问':[...new Set(u.acl.map(g=>({department:'部门',role:'角色',user:'个人',global:'全局'}[g.type])))].join(' + ')
function editAcl(unit:Unit){aclId.value=unit.id;acl.value=JSON.parse(JSON.stringify(unit.acl));aclOpen.value=true}
watch(units.items,rows=>{if(!grantOpened.value&&route.query.grant&&auth.has('knowledge.permissions')){const unit=rows.find(u=>u.id===route.query.grant);if(unit){grantOpened.value=true;editAcl(unit)}}})
async function saveAcl(){await task.run(async()=>{const updated=await service.save('units',{id:aclId.value,acl:acl.value});aclOpen.value=false;await units.load();if(route.query.grant===updated.id&&!updated.restricted)await router.push(`/knowledge/units/${updated.id}`)},'数据授权已更新')}
async function remove(ids:string[]){if(!await confirmAction(`删除选中的 ${ids.length} 个知识单元？关联 FAQ 将停止使用，引用失效，关联缺口将重新打开。`,'删除知识'))return;await task.run(async()=>{await service.remove('units',ids);selection.value=[];await units.load()},'知识已删除')}
function selectAll(e:Event){selection.value=(e.target as HTMLInputElement).checked?visible.value.filter(u=>!u.restricted).map(u=>u.id):[]}
</script>
<template><PageHeader title="知识单元" description="每一份文档，都是一份可授权、可引用的团队知识。"><RouterLink v-if="auth.has('knowledge.import')" to="/knowledge/import" class="btn quiet"><Icon name="upload"/>导入文档</RouterLink><RouterLink v-if="auth.has('knowledge.create')" to="/knowledge/units/new" class="btn primary"><Icon name="plus"/>新建知识</RouterLink></PageHeader><form class="filters" @submit.prevent><label class="search"><Icon name="search"/><input v-model="query" aria-label="搜索知识" placeholder="搜索标题、编号或标签"></label><select v-model="category" aria-label="知识分类"><option value="">全部分类</option><option v-for="c in categories" :key="c">{{c}}</option></select><select v-model="status" aria-label="发布状态"><option value="">全部状态</option><option value="published">已发布</option><option value="draft">草稿</option></select><button class="btn quiet" type="button" @click="query='';category='';status=''">重置</button></form><div v-if="selection.length" class="bulk-bar"><span>已选择 {{selection.length}} 项</span><button class="text-button danger" :disabled="task.busy.value" @click="remove(selection)">批量删除</button><button class="text-button" @click="selection=[]">取消选择</button></div><LoadState :loading="units.loading.value" :error="units.error.value" :empty="!filtered.length" empty-text="没有符合条件的知识，试试调整筛选。" @retry="units.load"><div class="table-wrap knowledge-table-wrap"><div v-if="auth.has('knowledge.delete')" class="mobile-table-select"><label class="check-label"><input type="checkbox" aria-label="选择本页可访问知识" @change="selectAll" :checked="visible.filter(u=>!u.restricted).length>0&&visible.filter(u=>!u.restricted).every(u=>selection.includes(u.id))">选择本页可访问知识</label></div><table class="data-table knowledge-table"><thead><tr><th v-if="auth.has('knowledge.delete')" class="table-check"><input type="checkbox" aria-label="选择本页可访问知识" @change="selectAll" :checked="visible.filter(u=>!u.restricted).length>0&&visible.filter(u=>!u.restricted).every(u=>selection.includes(u.id))"></th><th>编号 / 知识标题</th><th>分类</th><th>数据权限</th><th>更新时间 / 创建人</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="unit in visible" :key="unit.id"><td v-if="auth.has('knowledge.delete')"><input type="checkbox" v-model="selection" :value="unit.id" :disabled="unit.restricted" :aria-label="`选择 ${unit.code}`"></td><td><RouterLink v-if="!unit.restricted" :to="`/knowledge/units/${unit.id}`" class="identity">{{unit.title}}</RouterLink><span v-else class="identity muted">{{unit.title}}</span><span class="sub">{{unit.code}} · {{unit.fileType}}</span></td><td>{{unit.restricted?'—':unit.category}}</td><td><span :class="{'warning-text':!unit.acl.length}">{{grantLabel(unit)}}</span></td><td><span class="num">{{formatDate(unit.updatedAt)}}</span><span class="sub">{{unit.creatorId===auth.user?.id?'我创建':unit.creatorId}}</span></td><td><span class="status" :class="unit.status==='published'?'success':''">{{unit.status==='published'?'已发布':'草稿'}}</span></td><td><div class="row-actions"><RouterLink v-if="!unit.restricted" :to="`/knowledge/units/${unit.id}`" class="text-button">查看</RouterLink><RouterLink v-if="auth.has('knowledge.update')&&!unit.restricted" :to="`/knowledge/units/${unit.id}/edit`" class="text-button">编辑</RouterLink><button v-if="auth.has('knowledge.permissions')" class="text-button" @click="editAcl(unit)">授权</button><button v-if="auth.has('knowledge.delete')&&!unit.restricted" class="text-button danger" @click="remove([unit.id])">删除</button><span v-if="unit.restricted&&!auth.has('knowledge.permissions')" class="small faint">访问受限</span></div></td></tr></tbody></table><div class="mobile-records"><article v-for="unit in visible" :key="unit.id" class="mobile-record"><div class="record-heading"><input v-if="auth.has('knowledge.delete')" type="checkbox" v-model="selection" :value="unit.id" :disabled="unit.restricted" :aria-label="`选择 ${unit.code}`"><RouterLink v-if="!unit.restricted" :to="`/knowledge/units/${unit.id}`">{{unit.title}}</RouterLink><strong v-else>{{unit.title}}</strong><span class="status" :class="unit.status==='published'?'success':''">{{unit.status==='published'?'已发布':'草稿'}}</span></div><p class="small faint">{{unit.code}} · {{unit.fileType}} · {{unit.restricted?'受限':unit.category}}</p><p class="small muted">授权：{{grantLabel(unit)}}<br>{{formatDate(unit.updatedAt)}} · {{unit.creatorId===auth.user?.id?'我创建':unit.creatorId}}</p><div class="row-actions"><RouterLink v-if="!unit.restricted" :to="`/knowledge/units/${unit.id}`" class="text-button">查看详情</RouterLink><RouterLink v-if="auth.has('knowledge.update')&&!unit.restricted" :to="`/knowledge/units/${unit.id}/edit`" class="text-button">编辑</RouterLink><button v-if="auth.has('knowledge.permissions')" class="text-button" @click="editAcl(unit)">配置授权</button><button v-if="auth.has('knowledge.delete')&&!unit.restricted" class="text-button danger" @click="remove([unit.id])">删除</button></div></article></div></div><div class="table-footer"><span>共 {{filtered.length}} 项 · 第 {{page}} 页</span><el-pagination v-model:current-page="page" :page-size="10" :total="filtered.length" layout="prev,pager,next" /></div></LoadState><div class="notice" style="margin-top:20px">全局、部门、角色、个人任一授权匹配即可访问。未配置授权的知识默认不可访问。</div><el-dialog v-model="aclOpen" title="配置知识数据授权" width="560px" :close-on-click-modal="false"><PermissionSelector v-model="acl"/><p v-if="task.error.value" class="field-error">{{task.error.value}}</p><template #footer><button class="btn quiet" @click="aclOpen=false">取消</button><button class="btn primary" :disabled="task.busy.value" @click="saveAcl">保存授权</button></template></el-dialog></template>
<style scoped>.knowledge-table{min-width:1060px}.mobile-table-select{display:none}.record-heading>a,.record-heading>strong{flex:1}.record-heading>input{margin-top:5px}.warning-text{color:var(--warning)}.mobile-record{padding:18px 0;border-bottom:1px solid var(--line)}.mobile-record:last-child{border:0}.record-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;font-size:14px;font-weight:500;line-height:1.8}.mobile-record p{margin-top:9px}.mobile-record .row-actions{margin-top:12px}@media(max-width:640px){.knowledge-table{display:none}.mobile-table-select{display:flex;padding:16px 0;border-bottom:1px solid var(--line)}.mobile-records{display:block}.knowledge-table-wrap{overflow:visible}}</style>
